<script setup>
import { computed, ref, watch } from "vue";
import { RouterLink } from "vue-router";
import PaginationControls from "@/components/common/PaginationControls.vue";
const props = defineProps({ type: { type: String, required: true }, items: { type: Array, default: () => [] }, loading: Boolean, error: { type: String, default: "" }, createRoute: { type: String, required: true }, editRoute: { type: String, required: true } });
defineEmits(["delete"]);
const label = (type) => type === "department" ? "département" : "secteur";
const page = ref(1);
const perPage = 10;
const visibleItems = computed(() => props.items.slice((page.value - 1) * perPage, page.value * perPage));
watch(() => props.items.length, (count) => { if (page.value > Math.max(1, Math.ceil(count / perPage))) page.value = Math.max(1, Math.ceil(count / perPage)); });
</script>
<template>
  <section class="reference-page"><div class="page-toolbar"><div><p class="eyebrow">Administration / Référentiels</p><h2>{{ type === "department" ? "Départements" : "Secteurs" }}</h2><p class="description">Gérez séparément les éléments utilisés lors de la saisie des doléances.</p></div><RouterLink class="primary-button" :to="{ name: createRoute }">＋ Nouveau {{ label(type) }}</RouterLink></div><div v-if="error" class="alert">{{ error }}</div><div class="list-card"><div class="list-head"><div><h3>{{ type === "department" ? "Départements" : "Secteurs" }} enregistrés</h3><p>{{ items.length }} élément{{ items.length === 1 ? "" : "s" }}</p></div><span class="count-badge">{{ items.length }}</span></div><p v-if="loading" class="state">Chargement…</p><p v-else-if="!items.length" class="state">Aucun {{ label(type) }} enregistré.</p><div v-else class="reference-list"><div v-for="item in visibleItems" :key="item.id" class="reference-row"><div class="reference-symbol">{{ item.name.slice(0, 1).toUpperCase() }}</div><div class="reference-copy"><strong>{{ item.name }}</strong><small>{{ item.grievances_count || 0 }} doléance{{ item.grievances_count === 1 ? "" : "s" }}</small></div><RouterLink class="edit-link" :to="{ name: editRoute, params: { id: item.id } }">Modifier</RouterLink><button type="button" class="delete-link" :disabled="item.grievances_count > 0" @click="$emit('delete', item)">×</button></div></div><PaginationControls :current-page="page" :last-page="Math.max(1, Math.ceil(items.length / perPage))" :total="items.length" @change="page = $event" /></div></section>
</template>
<style scoped>
.reference-page{max-width:1180px;margin:0 auto}.page-toolbar{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem}.eyebrow{margin:0 0 .55rem;color:#6d91e4;font-size:.68rem;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.page-toolbar h2{margin:0;color:#1c2d46;font-size:2rem;letter-spacing:-.06em}.description{margin:.6rem 0 0;color:#8b99ab;font-size:.8rem}.primary-button{display:inline-flex;align-items:center;justify-content:center;padding:.72rem 1rem;border-radius:.55rem;color:#fff;background:linear-gradient(100deg,#3e70da,#5c82e4);font-size:.75rem;font-weight:700;text-decoration:none}.alert{margin-top:1.2rem;padding:.75rem;border:1px solid #ffd7db;border-radius:.6rem;color:#b33e4b;background:#fff3f4;font-size:.76rem}.list-card{margin-top:1.7rem;padding:1.25rem;border:1px solid #e8eef6;border-radius:.9rem;background:#fff;box-shadow:0 5px 15px rgb(30 52 84 / 3%)}.list-head{display:flex;justify-content:space-between}.list-head h3{margin:0;color:#253650;font-size:.95rem}.list-head p{margin:.3rem 0 0;color:#9aa7b7;font-size:.7rem}.count-badge{padding:.35rem .55rem;border-radius:.4rem;color:#557bd0;background:#eff4ff;font-size:.7rem;font-weight:800}.reference-list{margin-top:1rem}.reference-row{display:flex;align-items:center;gap:.7rem;padding:.8rem 0;border-top:1px solid #f0f3f7}.reference-symbol{display:grid;width:2.1rem;height:2.1rem;flex:0 0 auto;place-items:center;border-radius:.65rem;color:#4e7fe0;background:#eaf1ff;font-weight:800}.reference-copy{min-width:0;flex:1}.reference-copy strong,.reference-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reference-copy strong{color:#32425a;font-size:.78rem}.reference-copy small{margin-top:.18rem;color:#a4afbd;font-size:.63rem}.edit-link,.delete-link{border:0;background:none;cursor:pointer;font-size:.68rem;font-weight:700;text-decoration:none}.edit-link{color:#4f7bdd}.delete-link{display:grid;width:1.5rem;height:1.5rem;place-items:center;border-radius:.4rem;color:#d77a83;background:#fff1f2;font-size:1.05rem}.delete-link:disabled{cursor:not-allowed;opacity:.3}.state{padding:2rem;color:#9aa7b7;font-size:.78rem;text-align:center}@media(max-width:700px){.page-toolbar{display:block}.page-toolbar .primary-button{margin-top:1.1rem}.list-card{padding:.8rem}}
</style>
